    referenceData: { title: 'ZMI-specific planning fields', note: 'Variable altar output is exposed through the average rather than hidden.', headers: ['Field', 'Meaning', 'Recommended source'], rows: [['XP/essence', 'Level-weighted average', 'Current Wiki or sample'], ['Essence/hour', 'Full route throughput', 'Measured session'], ['Essence needed', 'Ceiling division', 'Calculated'], ['Target XP', 'Exact threshold', 'XP formula']] },
